mapper.select:
SELECT r.id AS memory_id, s.id AS spot_id, s.name AS spot_name, r.latitude AS latitude, r.longitude AS longitude, r.visited_date AS visited_date, r.nights AS nights, LEFT(r.content, 100) AS excerpt, r.visibility AS visibility, r.status AS status, , (SELECT COUNT(*) FROM memory_like l WHERE l.memory_id = r.id) AS like_count, r.created_at AS created_at FROM memory r LEFT JOIN spot s ON s.id = r.spot_id AND s.status = 'ACTIVE' WHERE r.member_id = #{memberId}
AND r.visibility = #{visibility} AND r.status = 'ACTIVE'
ORDER BY r.visited_date DESC, r.id DESC
